<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { userApi } from '@/api'
import type { User } from '@/types'
const rows=ref<User[]>([]); const loading=ref(false); const page=ref(1); const total=ref(0); const filters=reactive({keyword:'',role:'',status:''})
async function load(){loading.value=true;try{const r=await userApi.list({...filters,page:page.value,page_size:20});rows.value=r.data.data.list;total.value=r.data.pagination?.total||0}catch(e){ElMessage.error((e as Error).message)}finally{loading.value=false}}
async function toggle(row:User){if(row.role==='ADMIN')return ElMessage.warning('管理员账号不能被禁用');const next=row.status==='ACTIVE'?'DISABLED':'ACTIVE';try{await ElMessageBox.confirm(`确定${next==='DISABLED'?'封禁':'解除封禁'}用户“${row.username}”吗？`,'账号状态确认',{type:'warning'});await userApi.setStatus(row.user_id,next);ElMessage.success(next==='DISABLED'?'用户已封禁':'用户已解封');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.message||'操作失败')}}
onMounted(load)
</script>
<template><div class="panel page-stack"><div class="panel-head"><div><h3>用户管理</h3><p>管理员账号不可封禁，仅可封禁普通用户</p></div><div class="filter-bar"><el-input v-model="filters.keyword" placeholder="账号/昵称/手机号" clearable @keyup.enter="page=1;load()"/><el-select v-model="filters.role" placeholder="全部角色" clearable><el-option label="普通用户" value="USER"/><el-option label="管理员" value="ADMIN"/></el-select><el-button type="primary" @click="page=1;load()">筛选</el-button></div></div><el-table v-loading="loading" :data="rows" stripe><el-table-column prop="username" label="账号" min-width="130"/><el-table-column prop="nickname" label="昵称"/><el-table-column prop="student_no" label="学号"/><el-table-column prop="phone" label="手机号"/><el-table-column label="角色" width="100"><template #default="{row}"><el-tag :type="row.role==='ADMIN'?'warning':'info'">{{row.role==='ADMIN'?'管理员':'普通用户'}}</el-tag></template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='ACTIVE'?'success':'danger'">{{row.status==='ACTIVE'?'正常':'已封禁'}}</el-tag></template></el-table-column><el-table-column prop="last_login_at" label="最后登录" width="180"/><el-table-column label="操作" width="120"><template #default="{row}"><el-button v-if="row.role==='USER'" link :type="row.status==='ACTIVE'?'danger':'success'" @click="toggle(row)">{{row.status==='ACTIVE'?'封禁':'解除封禁'}}</el-button><span v-else class="muted">受保护</span></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="page" layout="prev, pager, next" :page-size="20" :total="total" @current-change="load"/></div></div></template>
